export function createBaseChartSettingsUnionWithDiscriminator(
  options:
    | ({ type: typeof ChartTypeEnum.line } & Partial<LineChartSettings>)
    | ({ type: typeof ChartTypeEnum.scatter } & Partial<ScatterChartSettings>),
): BaseChartSettingsUnion {
  switch (options.type) {
    case ChartTypeEnum.line:
      return createLineChartSettings(options);
    case ChartTypeEnum.scatter:
      return createScatterChartSettings(options);
    default:
      throw new Error("Unsupported chart type.");
  }
}

export type GeneratedAppGenerationMode =
  | "json_render"
  | "json_render_with_image"
  | "prompt_builder"
  | "mcp_server";

export const GeneratedAppGenerationModeEnum = {
  JSONRender: "json_render",
  JSONRenderWithImage: "json_render_with_image",
  PromptBuilder: "prompt_builder",
  MCPServer: "mcp_server",
} as const satisfies Record<string, GeneratedAppGenerationMode>;

export const GENERATED_PLAIN_CHAT_APP_GENERATION_MESSAGE_MODE = "plain_chat";

export function parseGeneratedAppGenerationMode(
  value: unknown,
): GeneratedAppGenerationMode | null {
  if (typeof value !== "string") {
    return null;
  }
  const trimmed = value.trim();
  if (!trimmed) {
    return null;
  }
  switch (trimmed) {
    case "json_render":
    case "json_render_with_image":
    case "prompt_builder":
    case "mcp_server":
      return trimmed;
    default:
      return null;
  }
}

